<?php
declare(strict_types=1);if(!defined('_GNUBOARD_')){http_response_code(403);exit;}
require_once __DIR__.'/taxonomy-store.php';require_once __DIR__.'/popularity-core.php';require_once __DIR__.'/home-core.php';
function np_json(mixed $v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
function np_ready(PDO $db):bool{return nc_exists($db,'noa_ranking_runs')&&nc_exists($db,'noa_valid_plays');}
function np_defaults():array{return ['minimumSeconds'=>30,'heartbeatMaxGap'=>20,'sessionMaxSeconds'=>1800,'songCooldownSeconds'=>1800,'actorHourlyLimit'=>20,'actorStartHourlyLimit'=>60,'youtubeStaleSeconds'=>172800,'playbackIntegrationEnabled'=>false];}
function np_policy(PDO $db):array{$r=$db->query('SELECT policy,revision FROM noa_popularity_settings WHERE id=1')->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('policy_missing');return ['values'=>json_decode($r['policy'],true,512,JSON_THROW_ON_ERROR),'revision'=>(int)$r['revision']];}
function np_validate_policy(array $p):void{
 $limits=['minimumSeconds'=>[30,300],'heartbeatMaxGap'=>[5,60],'sessionMaxSeconds'=>[300,7200],'songCooldownSeconds'=>[300,86400],'actorHourlyLimit'=>[1,120],'actorStartHourlyLimit'=>[1,240],'youtubeStaleSeconds'=>[3600,604800]];
 if(array_diff(array_keys($p),array_keys(np_defaults())))throw new DomainException('unknown_policy_key');foreach($limits as $k=>[$min,$max])if(!isset($p[$k])||!is_int($p[$k])||$p[$k]<$min||$p[$k]>$max)throw new DomainException('invalid_policy');if(!isset($p['playbackIntegrationEnabled'])||!is_bool($p['playbackIntegrationEnabled']))throw new DomainException('invalid_integration_flag');
}
function np_migrate(PDO $db,string $actor):array{
 $created=[];foreach(require __DIR__.'/popularity-schema.php' as $table=>$definition){$old=nc_exists($db,$table);if($old){$ddl=$db->query('SHOW CREATE TABLE `'.$table.'`')->fetch(PDO::FETCH_NUM)[1];preg_match_all('/(?:^\(|,)([a-z][a-z0-9_]*)\s+(?:VARCHAR|CHAR|LONGTEXT|JSON|INT|TINYINT|TIMESTAMP|BIGINT|DATETIME|DOUBLE)/i',$definition,$m);$columns=$db->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll(PDO::FETCH_COLUMN);if(array_diff($m[1],$columns))throw new DomainException('popularity_schema_conflict');}else{$db->exec('CREATE TABLE `'.$table.'` '.$definition.' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin');$created[]=$table;}}
 $q=$db->prepare('INSERT IGNORE INTO noa_popularity_settings(id,policy,updated_by) VALUES(1,?,?)');$q->execute([np_json(np_defaults()),$actor]);return $created;
}
function np_error(PDO $db,string $kind,string $code,?string $hour=null):void{$q=$db->prepare('INSERT INTO noa_ranking_errors(kind,code,hour_utc) VALUES(?,?,?)');$q->execute([$kind,substr($code,0,64),$hour]);}
function np_inputs(PDO $db,int $cutoff):array{
 $q=$db->prepare("SELECT * FROM noa_youtube_runs WHERE channel_id=? AND created_at<=? ORDER BY created_at DESC,run_id DESC LIMIT 1");$q->execute([NP_CHANNEL,gmdate('Y-m-d H:i:s',$cutoff)]);$run=$q->fetch(PDO::FETCH_ASSOC);if(!$run)throw new DomainException('collection_before_hour_required');
 $lists=[];$membership=[];$q=$db->prepare('SELECT payload FROM noa_youtube_playlists WHERE run_id=?');$q->execute([$run['run_id']]);foreach($q as $r)$lists[]=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);
 $q=$db->prepare('SELECT playlist_id,video_id FROM noa_youtube_items WHERE run_id=? ORDER BY position,item_id');$q->execute([$run['run_id']]);foreach($q as $r)$membership[$r['playlist_id']][]=$r['video_id'];
 $q=$db->prepare('SELECT song_id,COUNT(*) AS n FROM noa_valid_plays WHERE accepted_at<? GROUP BY song_id');$q->execute([$cutoff]);$plays=[];foreach($q as $r)$plays[$r['song_id']]=(int)$r['n'];$songCats=[];foreach($db->query("SELECT content_id,category_id FROM noa_content_categories WHERE content_type='song' AND active=1")as $r)$songCats[$r['content_id']][]=$r['category_id'];
 $raw=ny_videos($db,$run);foreach($db->query("SELECT m.content_id,a.genre_id FROM noa_playlist_matches m JOIN noa_catalog_acts a ON a.act_id=m.catalog_playlist_id WHERE m.content_type='video' AND m.status='confirmed'")as $r)if(isset($raw[$r['content_id']]))$raw[$r['content_id']]['sqlGenre']=$r['genre_id'];$report=json_decode($run['report'],true,512,JSON_THROW_ON_ERROR);return ['raw'=>$raw,'songs'=>ny_songs($db,ny_batch($db)),'lists'=>$lists,'membership'=>$membership,'plays'=>$plays,'categories'=>nt_categories($db),'songCats'=>$songCats,'run'=>$run,'syncedAt'=>$report['completedAt']??$run['created_at']];
}
function np_calculate(PDO $db,?int $now=null):array{
 $now??=time();$cutoff=intdiv($now,3600)*3600;$hour=gmdate('Y-m-d H:i:s',$cutoff);$previous=gmdate('Y-m-d H:i:s',$cutoff-3600);
 if(!(int)$db->query("SELECT GET_LOCK('noa_popularity_writer',0)")->fetchColumn())throw new DomainException('ranking_busy');
 try{
  $q=$db->prepare("SELECT summary FROM noa_ranking_runs WHERE hour_utc=? AND status='published'");$q->execute([$hour]);if($old=$q->fetchColumn())return json_decode($old,true,512,JSON_THROW_ON_ERROR)+['replayed'=>true];
  $db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$db->beginTransaction();$policy=np_policy($db);$in=np_inputs($db,$cutoff);$built=np_build($in['raw'],$in['songs'],$in['lists'],$in['membership'],$in['plays'],$in['categories'],$in['songCats']);
  if(count($in['songs'])===0||count($built['groups']['songs'])===0||$built['totals']['countedVideos']===0)throw new DomainException('empty_or_invalid_ranking');
  $q=$db->prepare("SELECT rules_version FROM noa_ranking_runs WHERE hour_utc=? AND status='published'");$q->execute([$previous]);$priorVersion=$q->fetchColumn();$hasPrevious=$priorVersion===NP_VERSION;$q=$db->prepare('SELECT rank_type,content_id,current_rank FROM noa_ranking_rows WHERE hour_utc=?');$q->execute([$previous]);$old=[];foreach($q as $r)$old[$r['rank_type']][$r['content_id']]=(int)$r['current_rank'];
  $q=$db->prepare('INSERT INTO noa_ranking_rows(hour_utc,rank_type,group_id,content_id,youtube_views,jukebox_plays,score,current_rank,previous_rank,rank_delta,rank_state,payload) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$counts=[];
  foreach($built['groups'] as $type=>$rows){$counts[$type]=count($rows);$seen=[];foreach($rows as $i=>$r){if(isset($seen[$r['contentId']]))throw new DomainException('duplicate_ranking_content');$seen[$r['contentId']]=true;$rank=$i+1;$r+=np_movement($old[$type][$r['contentId']]??null,$rank,$hasPrevious);$r['rank']=$rank;$r['aggregatedAt']=gmdate('c',$cutoff);$r['youtubeSyncedAt']=$in['syncedAt'];$r['rulesVersion']=NP_VERSION;$q->execute([$hour,$type,'all',$r['contentId'],$r['youtubeViews'],$r['jukeboxPlays'],$r['score'],$rank,$r['previousRank'],$r['rankDelta'],$r['rankState'],np_json($r)]);}}
  $summary=['hour'=>gmdate('c',$cutoff),'computedAt'=>gmdate('c',$now),'youtubeSyncedAt'=>$in['syncedAt'],'collectionId'=>$in['run']['run_id'],'totals'=>$built['totals'],'counts'=>$counts,'rulesVersion'=>NP_VERSION,'previousHourAvailable'=>$hasPrevious,'previousHourPresent'=>(bool)$priorVersion,'comparisonUnavailableReason'=>$hasPrevious?null:($priorVersion?'rule_version_changed':'missing_prior_hour'),'jukeboxCollectionStatus'=>$policy['values']['playbackIntegrationEnabled']?'enabled':'awaiting_music_integration','policyRevision'=>$policy['revision']];
  $q=$db->prepare("INSERT INTO noa_ranking_runs(hour_utc,status,collection_id,youtube_synced_at,rules_version,policy_revision,summary) VALUES(?,'published',?,?,?,?,?)");$q->execute([$hour,$in['run']['run_id'],$in['syncedAt'],NP_VERSION,$policy['revision'],np_json($summary)]);$db->commit();return $summary+['replayed'=>false];
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();try{np_error($db,'aggregation',$e instanceof DomainException?$e->getMessage():get_class($e).':'.$e->getCode(),$hour);}catch(Throwable $ignored){}throw $e;}finally{$db->query("SELECT RELEASE_LOCK('noa_popularity_writer')");}
}
function np_public(PDO $db,string $type='featured',int $limit=10,?string $hour=null):array{
 if(!in_array($type,['featured','ep','stories','covers','playlists','genres','genre_totals','collections','jukebox','mv','songs'],true))throw new DomainException('unknown_rank_type');$limit=max(1,min(1000,$limit));
 if($hour===null){$run=$db->query("SELECT * FROM noa_ranking_runs WHERE status='published' ORDER BY hour_utc DESC LIMIT 1")->fetch(PDO::FETCH_ASSOC);}else{$q=$db->prepare("SELECT * FROM noa_ranking_runs WHERE status='published' AND hour_utc=?");$q->execute([$hour]);$run=$q->fetch(PDO::FETCH_ASSOC);}
 if(!$run)return ['ok'=>true,'available'=>false,'rankType'=>$type,'items'=>[],'count'=>0,'totalCount'=>0,'featuredContent'=>null];
 $q=$db->prepare('SELECT payload FROM noa_ranking_rows WHERE hour_utc=? AND rank_type=? AND group_id=\'all\' ORDER BY current_rank LIMIT 1000');$q->execute([$run['hour_utc'],$type]);$items=[];foreach($q as $r)$items[]=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);$items=np_visibility_filter($db,$run['collection_id'],$items);$visibleCount=count($items);$unranked=np_unranked_genres($db,$type,$items);$cards=array_slice(array_merge($items,$unranked),0,$limit);$cardCount=$visibleCount+count($unranked);$items=array_slice($items,0,$limit);$s=json_decode($run['summary'],true,512,JSON_THROW_ON_ERROR);$policy=np_policy($db)['values'];
 return ['ok'=>true,'available'=>true,'rankType'=>$type,'cards'=>$cards,'cardCount'=>$cardCount,'unrankedCount'=>count($unranked),'items'=>$items,'count'=>count($items),'totalCount'=>$visibleCount,'featuredContent'=>$items[0]??null,'aggregatedAt'=>$s['hour'],'computedAt'=>$s['computedAt'],'youtubeSyncedAt'=>$s['youtubeSyncedAt'],'youtubeStale'=>time()-(strtotime($s['youtubeSyncedAt'])?:0)>$policy['youtubeStaleSeconds'],'rankingStale'=>time()-(strtotime($s['hour'])?:0)>7200,'rulesVersion'=>$s['rulesVersion'],'jukeboxCollectionStatus'=>$s['jukeboxCollectionStatus'],'totals'=>$s['totals'],'movementIcons'=>['up'=>['icon'=>'trending-up','color'=>'green'],'down'=>['icon'=>'trending-down','color'=>'red'],'same'=>['icon'=>'minus','color'=>'gray'],'new'=>['label'=>'NEW'],'unknown'=>null]];
}
function np_home(PDO $db,array $legacy):array{
 if(!np_ready($db))return $legacy;$first=np_public($db);if(!$first['available'])return $legacy;
 foreach(['featured','ep','stories','covers','playlists']as $type)$legacy[$type]=$type==='featured'?$first['items']:np_public($db,$type,10,str_replace(['T','+00:00'],[' ',''],$first['aggregatedAt']))['items'];
 $legacy['popularity']=array_intersect_key($first,array_flip(['aggregatedAt','computedAt','youtubeSyncedAt','youtubeStale','rankingStale','rulesVersion','jukeboxCollectionStatus','totals']));$legacy['basis']='youtube_public_views_plus_verified_jukebox_plays';$legacy['playlistBasis']='공식 목록은 중복 없는 공개 수록 영상 조회수와 중복 없는 곡별 유효 재생수 합계, 연속듣기 영상은 해당 영상과 연결된 곡의 점수입니다. 목록 자체 조회수를 더하지 않습니다.';return $legacy;
}

/** Hide newly private/deleted source rows immediately, retaining immutable ranks. */
function np_visibility_filter(PDO $db,string $source,array $items):array{
 $latest=ny_latest($db);if(!$latest||$latest['run_id']===$source)return $items;$visible=[];$q=$db->prepare('SELECT video_id,payload FROM noa_youtube_videos WHERE run_id=?');$q->execute([$latest['run_id']]);foreach($q as $r){$v=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);if(nh_public($v,NP_CHANNEL,true))$visible[$r['video_id']]=true;}$lists=[];$q=$db->prepare('SELECT playlist_id,payload FROM noa_youtube_playlists WHERE run_id=?');$q->execute([$latest['run_id']]);foreach($q as $r)if(nh_public(json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR),NP_CHANNEL))$lists[$r['playlist_id']]=true;
 return array_values(array_filter($items,function($r)use($visible,$lists){if($r['contentType']==='video')return isset($visible[$r['videoId']]);if($r['contentType']==='youtube_playlist')return isset($lists[$r['playlistId']]);if($r['contentType']==='song'&&!empty($r['youtubeVideoIds']))return (bool)array_intersect($r['youtubeVideoIds'],array_keys($visible));return true;}));
}

/** Existing registered genre cards without verified metrics remain visible with null score. */
function np_unranked_genres(PDO $db,string $type,array $ranked):array{
 if(!in_array($type,['genres','genre_totals','collections'],true))return [];$songs=ny_songs($db,ny_batch($db));$cats=array_column(nt_categories($db),null,'category_id');$collection=[];
 foreach($db->query("SELECT content_id,category_id FROM noa_content_categories WHERE content_type='song' AND active=1")as $r){$cat=$r['category_id'];$seen=[];while(isset($cats[$cat])&&!isset($seen[$cat])){$seen[$cat]=true;if($cat==='collection'&&isset($songs[$r['content_id']]))$collection[$songs[$r['content_id']]['genre_id']]=true;$cat=$cats[$cat]['parent_id'];if($cat===null)break;}}
 $registered=[];foreach($songs as $s)$registered[$s['genre_id']]=($registered[$s['genre_id']]??0)+1;$present=array_fill_keys(array_column($ranked,'contentId'),true);ksort($registered,SORT_STRING);$out=[];
 foreach($registered as $id=>$count){if(isset($present[$id])||($type==='collections'&&!isset($collection[$id]))||($type==='genres'&&!str_ends_with($id,'-original')))continue;$out[]=['contentId'=>$id,'contentType'=>'genre','title'=>np_genre_titles()[$id]??$id,'genre'=>$id,'registeredSongs'=>$count,'youtubeViews'=>null,'jukeboxPlays'=>null,'score'=>null,'rank'=>null,'previousRank'=>null,'rankDelta'=>null,'rankState'=>'unknown','metricStatus'=>'no_confirmed_public_video_metrics','href'=>'/noa-music.php?genre='.rawurlencode($id)];}return $out;
}
